	key: string;
	/** Pack display name, e.g. "Nango — Google Workspace". */
	name: string;
	description?: string | null;
	source: "available" | "installed";
	status: CapabilityCardStatus;
	connection?: CapabilityCardConnection;
	verbs: CapabilityCardVerb[];
